// Example of At-least-once processing with manual offset management
try {
    ConsumerRecords<String, String> records = consumer.poll(Duration.ofMillis(100));
    for (ConsumerRecord<String, String> record : records) {
        // Process business logic first
        process(record);
    }
    // Commit offsets only after successful processing
    consumer.commitSync(); 
} catch (Exception e) {
    // On failure, the offset is not committed, causing a re-read of the batch
    handleFailure(e);
}
